#!/usr/bin/env python3
"""Offline finite-domain rule mining service.

Reads one JSON request on stdin, writes one JSON response on stdout.
"""

import sys
import re
import json
from fractions import Fraction
from itertools import combinations, product

# --------------------------------------------------------------------------- #
# errors
# --------------------------------------------------------------------------- #

class EJson(Exception):
    pass


class ESchema(Exception):
    pass


def schema_fail():
    raise ESchema()


# --------------------------------------------------------------------------- #
# constants
# --------------------------------------------------------------------------- #

INT32_MIN = -2147483648
INT32_MAX = 2147483647
INPUT_LIMIT = 8388608
MAX_DEPTH = 64

NAME_RE = re.compile(r'[a-z][a-z0-9_]{0,31}\Z')
IDVAL_RE = re.compile(r'[A-Za-z0-9_.:-]{1,32}\Z')
TRACEID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')

NUMERIC_TYPES = frozenset(('TIME', 'SIZE', 'COUNT'))
ALL_TYPES = frozenset(('TIME', 'SIZE', 'COUNT', 'ID', 'FLAG'))
AGG_OPS = frozenset(('sum', 'mean', 'min', 'max'))
CMP_OPS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge'))

# non-integer JSON number sentinel (e.g. 1.0, 1e0, 1e999)
NONINT = object()


def is_int(v):
    return type(v) is int


# --------------------------------------------------------------------------- #
# input
# --------------------------------------------------------------------------- #

def read_stdin():
    """Return the raw input bytes, or None when the size limit is exceeded."""
    chunks = []
    total = 0
    read = sys.stdin.buffer.read
    while True:
        chunk = read(1 << 20)
        if not chunk:
            break
        total += len(chunk)
        if total > INPUT_LIMIT:
            return None
        chunks.append(chunk)
    return b''.join(chunks)


# --------------------------------------------------------------------------- #
# JSON parsing (strict RFC 8259 subset with the extra E_JSON conditions)
# --------------------------------------------------------------------------- #

_STRUCT_RE = re.compile(
    r'"(?:[^"\\\x00-\x1f]|\\(?:["\\/bfnrt]|u[0-9a-fA-F]{4}))*"'  # strings
    r'|[\[\]{}]'                                                 # structural
    r'|[^"\[\]{}]+'                                              # boring runs
)


def check_depth(text):
    depth = 0
    for match in _STRUCT_RE.finditer(text):
        tok = match.group()
        c = tok[0]
        if c == '[' or c == '{':
            depth += 1
            if depth > MAX_DEPTH:
                raise EJson()
        elif c == ']' or c == '}':
            depth -= 1


def parse_json(raw):
    if raw[:3] == b'\xef\xbb\xbf':
        raise EJson()
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise EJson()
    if text[:1] == '\ufeff':
        raise EJson()

    check_depth(text)

    def pairs_hook(pairs):
        obj = {}
        for key, val in pairs:
            if key in obj:
                raise EJson()
            obj[key] = val
        return obj

    def const_hook(_name):
        raise EJson()

    try:
        return json.loads(text,
                          object_pairs_hook=pairs_hook,
                          parse_constant=const_hook,
                          parse_float=lambda _s: NONINT)
    except EJson:
        raise
    except Exception:
        raise EJson()


# --------------------------------------------------------------------------- #
# schema
# --------------------------------------------------------------------------- #

def validate_schema(arr):
    """Return (names, types, domains)."""
    if type(arr) is not list or not (1 <= len(arr) <= 32):
        schema_fail()
    names = []
    types = []
    domains = []
    seen = set()
    for field in arr:
        if type(field) is not dict:
            schema_fail()
        keys = set(field.keys())
        if 'name' not in keys or 'type' not in keys:
            schema_fail()
        name = field['name']
        if type(name) is not str or not NAME_RE.fullmatch(name):
            schema_fail()
        ftype = field['type']
        if name in seen:
            schema_fail()
        seen.add(name)
        if ftype == 'TIME' or ftype == 'SIZE' or ftype == 'COUNT':
            if keys != {'name', 'type', 'min', 'max'}:
                schema_fail()
            lo = field['min']
            hi = field['max']
            if type(lo) is not int or type(hi) is not int:
                schema_fail()
            if not (INT32_MIN <= lo <= INT32_MAX) or not (INT32_MIN <= hi <= INT32_MAX):
                schema_fail()
            if lo > hi:
                schema_fail()
            domains.append((lo, hi))
        elif ftype == 'ID':
            if keys != {'name', 'type', 'values'}:
                schema_fail()
            values = field['values']
            if type(values) is not list or not (1 <= len(values) <= 32):
                schema_fail()
            vset = set()
            for val in values:
                if type(val) is not str or not IDVAL_RE.fullmatch(val):
                    schema_fail()
                if val in vset:
                    schema_fail()
                vset.add(val)
            domains.append(frozenset(vset))
        elif ftype == 'FLAG':
            if keys != {'name', 'type'}:
                schema_fail()
            domains.append(None)
        else:
            schema_fail()
        names.append(name)
        types.append(ftype)
    return names, types, domains


# --------------------------------------------------------------------------- #
# typed AST
# --------------------------------------------------------------------------- #

def compile_term(node, k, dollar_ok, ftypes, fidx):
    """Return (type, fn(ctx, dollar_row) -> value, node_count, depth)."""
    if type(node) is not dict:
        schema_fail()
    keys = set(node.keys())

    if keys == {'field', 'at'}:
        name = node['field']
        if type(name) is not str or name not in fidx:
            schema_fail()
        fi = fidx[name]
        ftype = ftypes[fi]
        at = node['at']
        if type(at) is str:
            if at != '$' or not dollar_ok:
                schema_fail()
            fn = lambda ctx, dr, _fi=fi: dr[_fi]
        elif type(at) is int and 0 <= at < k:
            fn = lambda ctx, dr, _fi=fi, _at=at: ctx[_at][_fi]
        else:
            schema_fail()
        return ftype, fn, 1, 1

    if keys == {'const', 'type'}:
        ctype = node['type']
        cval = node['const']
        if ctype in NUMERIC_TYPES:
            if type(cval) is not int or not (INT32_MIN <= cval <= INT32_MAX):
                schema_fail()
        elif ctype == 'ID':
            if type(cval) is not str or not IDVAL_RE.fullmatch(cval):
                schema_fail()
        elif ctype == 'FLAG':
            if type(cval) is not bool:
                schema_fail()
        else:
            schema_fail()
        return ctype, lambda ctx, dr, _v=cval: _v, 1, 1

    if keys == {'scale', 'term'}:
        scale = node['scale']
        if type(scale) is not int or not (-1024 <= scale <= 1024):
            schema_fail()
        ctype, cfn, cn, cd = compile_term(node['term'], k, dollar_ok, ftypes, fidx)
        if ctype not in NUMERIC_TYPES:
            schema_fail()
        if scale == 1:
            fn = cfn
        elif scale == 0:
            fn = lambda ctx, dr, _c=cfn: 0
        elif scale == -1:
            fn = lambda ctx, dr, _c=cfn: -_c(ctx, dr)
        else:
            fn = lambda ctx, dr, _c=cfn, _s=scale: _c(ctx, dr) * _s
        return ctype, fn, cn + 1, cd + 1

    if keys == {'add'}:
        arr = node['add']
        if type(arr) is not list or len(arr) != 2:
            schema_fail()
        t1, f1, n1, d1 = compile_term(arr[0], k, dollar_ok, ftypes, fidx)
        t2, f2, n2, d2 = compile_term(arr[1], k, dollar_ok, ftypes, fidx)
        if t1 not in NUMERIC_TYPES or t2 not in NUMERIC_TYPES or t1 != t2:
            schema_fail()
        fn = lambda ctx, dr, _a=f1, _b=f2: _a(ctx, dr) + _b(ctx, dr)
        return t1, fn, n1 + n2 + 1, (d1 if d1 >= d2 else d2) + 1

    if keys == {'aggregate', 'field', 'from', 'to'}:
        op = node['aggregate']
        if op not in AGG_OPS:
            schema_fail()
        name = node['field']
        if type(name) is not str or name not in fidx:
            schema_fail()
        fi = fidx[name]
        ftype = ftypes[fi]
        if ftype not in NUMERIC_TYPES:
            schema_fail()
        lo = node['from']
        hi = node['to']
        if type(lo) is not int or type(hi) is not int:
            schema_fail()
        if not (0 <= lo <= hi < k):
            schema_fail()
        offs = tuple(range(lo, hi + 1))
        if op == 'sum':
            fn = lambda ctx, dr, _o=offs, _fi=fi: sum([ctx[o][_fi] for o in _o])
        elif op == 'mean':
            fn = (lambda ctx, dr, _o=offs, _fi=fi, _n=len(offs):
                  Fraction(sum([ctx[o][_fi] for o in _o]), _n))
        elif op == 'min':
            fn = lambda ctx, dr, _o=offs, _fi=fi: min([ctx[o][_fi] for o in _o])
        else:
            fn = lambda ctx, dr, _o=offs, _fi=fi: max([ctx[o][_fi] for o in _o])
        return ftype, fn, 1, 1

    schema_fail()


_CMP_FNS = {
    'eq': lambda a, b: a == b,
    'ne': lambda a, b: a != b,
    'lt': lambda a, b: a < b,
    'le': lambda a, b: a <= b,
    'gt': lambda a, b: a > b,
    'ge': lambda a, b: a >= b,
}


def compile_comparison(node, k, dollar_ok, ftypes, fidx):
    """Return (fn(ctx, dollar_row) -> bool, node_count)."""
    if type(node) is not dict or set(node.keys()) != {'cmp', 'left', 'right'}:
        schema_fail()
    op = node['cmp']
    if op not in CMP_OPS:
        schema_fail()
    t1, f1, n1, d1 = compile_term(node['left'], k, dollar_ok, ftypes, fidx)
    t2, f2, n2, d2 = compile_term(node['right'], k, dollar_ok, ftypes, fidx)
    if t1 != t2:
        schema_fail()
    if n1 + n2 > 64:
        schema_fail()
    if d1 > 4 or d2 > 4:
        schema_fail()
    if t1 not in NUMERIC_TYPES and op not in ('eq', 'ne'):
        schema_fail()
    cmp_fn = _CMP_FNS[op]
    fn = lambda ctx, dr, _a=f1, _b=f2, _c=cmp_fn: _c(_a(ctx, dr), _b(ctx, dr))
    return fn, n1 + n2


def compile_atom(node, k, ftypes, fidx):
    """Return fn(ctx) -> bool."""
    if type(node) is not dict:
        schema_fail()
    keys = set(node.keys())
    if keys == {'quantifier', 'from', 'to', 'predicate'}:
        quant = node['quantifier']
        if quant not in ('any', 'all'):
            schema_fail()
        lo = node['from']
        hi = node['to']
        if type(lo) is not int or type(hi) is not int:
            schema_fail()
        if not (0 <= lo <= hi < k):
            schema_fail()
        pred, _ = compile_comparison(node['predicate'], k, True, ftypes, fidx)
        if lo == hi:
            return lambda ctx, _p=pred, _o=lo: _p(ctx, ctx[_o])
        if quant == 'any':
            return (lambda ctx, _p=pred, _a=lo, _z=hi:
                    any(_p(ctx, ctx[o]) for o in range(_a, _z + 1)))
        return (lambda ctx, _p=pred, _a=lo, _z=hi:
                all(_p(ctx, ctx[o]) for o in range(_a, _z + 1)))
    fn, _ = compile_comparison(node, k, False, ftypes, fidx)
    return lambda ctx, _p=fn: _p(ctx, None)


# --------------------------------------------------------------------------- #
# traces
# --------------------------------------------------------------------------- #

def check_row(values, types, domains):
    if type(values) is not list or len(values) != len(types):
        schema_fail()
    out = []
    for val, ftype, dom in zip(values, types, domains):
        if ftype in NUMERIC_TYPES:
            if type(val) is not int or not (dom[0] <= val <= dom[1]):
                schema_fail()
        elif ftype == 'ID':
            if type(val) is not str or val not in dom:
                schema_fail()
        else:
            if type(val) is not bool:
                schema_fail()
        out.append(val)
    return tuple(out)


def parse_traces(arr, types, domains, seen_ids, row_counter):
    if type(arr) is not list:
        schema_fail()
    out = []
    for trace in arr:
        if type(trace) is not dict or set(trace.keys()) != {'id', 'source', 'rows'}:
            schema_fail()
        tid = trace['id']
        src = trace['source']
        if type(tid) is not str or not TRACEID_RE.fullmatch(tid):
            schema_fail()
        if tid in seen_ids:
            schema_fail()
        seen_ids.add(tid)
        if type(src) is not str or not TRACEID_RE.fullmatch(src):
            schema_fail()
        rows = trace['rows']
        if type(rows) is not list:
            schema_fail()
        parsed = []
        for row in rows:
            if type(row) is not dict or set(row.keys()) != {'t', 'values'}:
                schema_fail()
            t = row['t']
            if type(t) is not int or not (INT32_MIN <= t <= INT32_MAX):
                schema_fail()
            parsed.append((t, check_row(row['values'], types, domains)))
        row_counter[0] += len(parsed)
        parsed.sort(key=lambda item: item[0])
        prev = None
        for t, _vals in parsed:
            if t == prev:
                schema_fail()
            prev = t
        out.append((tid, src, [vals for _t, vals in parsed]))
    return out


def count_contexts(traces, k):
    total = 0
    for _tid, _src, rows in traces:
        n = len(rows)
        if n >= k:
            total += n - k + 1
    return total


def build_contexts(traces, k, want_meta):
    ctxs = []
    meta = []
    for tid, src, rows in traces:
        n = len(rows)
        if n < k:
            continue
        for i in range(n - k + 1):
            ctxs.append(tuple(rows[i:i + k]))
            if want_meta:
                meta.append((tid, src, rows[i + k - 1]))
    return ctxs, meta


# --------------------------------------------------------------------------- #
# bit helpers
# --------------------------------------------------------------------------- #

_BIT_TABLES = [bytes(1 if (v >> p) & 1 else 0 for v in range(256))
               for p in range(8)]


def column_counts(items, D):
    """items: list of (mask, weight) with mask < 2**D.

    Returns a list of D integers: for each bit position d, the total weight of
    items whose mask has bit d set.
    """
    res = [0] * D
    if D == 0 or not items:
        return res
    nb = (D + 7) >> 3
    tables = _BIT_TABLES
    from_bytes = int.from_bytes
    chunk = []
    cw = 0

    def flush(entries):
        accs = [0] * 8
        for mask, wt in entries:
            data = mask.to_bytes(nb, 'little')
            if wt == 1:
                for p in range(8):
                    accs[p] += from_bytes(data.translate(tables[p]), 'little')
            else:
                for p in range(8):
                    accs[p] += from_bytes(data.translate(tables[p]), 'little') * wt
        for p in range(8):
            acc = accs[p]
            if not acc:
                continue
            data = acc.to_bytes(nb, 'little')
            for j in range(nb):
                v = data[j]
                if v:
                    idx = (j << 3) | p
                    if idx < D:
                        res[idx] += v

    for mask, wt in items:
        if cw + wt > 255 and chunk:
            flush(chunk)
            chunk = []
            cw = 0
        chunk.append((mask, wt))
        cw += wt
    if chunk:
        flush(chunk)
    return res


# --------------------------------------------------------------------------- #
# learning
# --------------------------------------------------------------------------- #

def iter_clauses(natoms, max_width):
    top = max_width if max_width < natoms else natoms
    for width in range(1, top + 1):
        for combo in combinations(range(natoms), width):
            if width == 1:
                yield (combo[0] * 2,)
                yield (combo[0] * 2 + 1,)
            else:
                for signs in product((0, 1), repeat=width):
                    yield tuple(combo[j] * 2 + signs[j] for j in range(width))


def learn(train_vecs, train_sources, probe_vecs, natoms, B, S, W):
    """Return a list of (signature_int, [clause literals...])."""
    n_train = len(train_vecs)
    n_probe = len(probe_vecs)
    if natoms == 0 or n_train == 0 or n_probe == 0 or not train_sources:
        return []
    full = (1 << n_train) - 1
    probe_full = (1 << n_probe) - 1

    # per-atom bitmasks over training contexts
    pos_mask = [0] * natoms
    bit = 1
    for vec in train_vecs:
        for a in range(natoms):
            if vec[a]:
                pos_mask[a] |= bit
        bit <<= 1

    # per-atom bitmasks over probe contexts
    probe_pos = [0] * natoms
    bit = 1
    for vec in probe_vecs:
        for a in range(natoms):
            if vec[a]:
                probe_pos[a] |= bit
        bit <<= 1

    src_masks = []
    for src in train_sources:
        mask = 0
        bit = 1
        for s in train_sources_iter(train_sources, src, n_train):
            pass
        src_masks.append(mask)

    return []


def train_source_masks(source_names, ctx_sources, n_train):
    masks = []
    for name in source_names:
        mask = 0
        bit = 1
        for src in ctx_sources:
            if src == name:
                mask |= bit
            bit <<= 1
        masks.append(mask)
    return masks


# --------------------------------------------------------------------------- #
# driver
# --------------------------------------------------------------------------- #

def process(obj):
    if type(obj) is not dict:
        schema_fail()
    if set(obj.keys()) != {'version', 'schema', 'window', 'atoms', 'policy',
                           'train', 'probes', 'queries'}:
        schema_fail()
    if type(obj['version']) is not int or obj['version'] != 1:
        schema_fail()
    k = obj['window']
    if type(k) is not int or not (1 <= k <= 8):
        schema_fail()

    names, types, domains = validate_schema(obj['schema'])
    fidx = {}
    for i, name in enumerate(names):
        fidx[name] = i

    atom_asts = obj['atoms']
    if type(atom_asts) is not list or len(atom_asts) > 20:
        schema_fail()
    atom_fns = []
    cache = {}
    for ast in atom_asts:
        try:
