    if type(S) is not int or not (1 <= S <= 4096):
        schema_fail()
    if type(W) is not int or not (1 <= W <= 4096):
        schema_fail()

    seen_ids = set()
    counter = [0]
    train_traces = parse_traces(obj['train'], types, domains, seen_ids, counter)
    probe_traces = parse_traces(obj['probes'], types, domains, seen_ids, counter)
    query_traces = parse_traces(obj['queries'], types, domains, seen_ids, counter)
    if counter[0] > 16384:
        schema_fail()
    if len(train_traces) + len(probe_traces) + len(query_traces) > 128:
