def emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(',', ':')))
    sys.stdout.write('\n')
    sys.stdout.flush()


def main():
    raw = read_stdin()
    if raw is None:
        emit({'error': 'E_LIMIT'})
        return 0
    try:
        obj = parse_json(raw)
    except EJson:
        emit({'error': 'E_JSON'})
        return 0
    try:
        result = process(obj)
    except ESchema:
        emit({'error': 'E_SCHEMA'})
        return 0
    except Exception:
        import traceback
        traceback.print_exc(file=sys.stderr)
        emit({'error': 'E_SCHEMA'})
        return 0
    emit(result)
    return 0


if __name__ == '__main__':
    sys.exit(main())
