"""Random valid-request generator for differential testing."""
import json
import random

NUM = ('TIME', 'SIZE', 'COUNT')
IDCH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.:-'


def rand_name(rnd):
    return rnd.choice('abcdefghijklmnopqrstuvwxyz') + ''.join(
        rnd.choice('abcdefghijklmnopqrstuvwxyz0123456789_')
        for _ in range(rnd.randint(0, 8)))


def rand_id_string(rnd):
    return ''.join(rnd.choice(IDCH) for _ in range(rnd.randint(1, 10)))


def gen_term(rnd, schema, k, dollar_ok, depth_budget):
    kinds = ['field', 'const']
    if depth_budget > 0:
        kinds += ['scale', 'add', 'aggregate']
    kind = rnd.choice(kinds)
    if kind == 'field':
        f = rnd.choice(schema)
        at = '$' if (dollar_ok and rnd.random() < 0.4) else rnd.randrange(k)
        return {'field': f['name'], 'at': at}
    if kind == 'const':
        f = rnd.choice(schema)
        t = f['type']
        if t in NUM:
            return {'const': rnd.randint(f['min'], f['max']), 'type': t}
        if t == 'ID':
            if rnd.random() < 0.7:
                return {'const': rnd.choice(f['values']), 'type': 'ID'}
            return {'const': rand_id_string(rnd), 'type': 'ID'}
        return {'const': rnd.random() < 0.5, 'type': 'FLAG'}
    if kind == 'scale':
        # must be numeric
        numfields = [f for f in schema if f['type'] in NUM]
        inner = gen_term(rnd, numfields, k, dollar_ok, depth_budget - 1)
        return {'scale': rnd.randint(-1024, 1024), 'term': inner}
    if kind == 'add':
        numfields = [f for f in schema if f['type'] in NUM]
        t1 = gen_term(rnd, numfields, k, dollar_ok, depth_budget - 1)
        t2 = gen_term(rnd, numfields, k, dollar_ok, depth_budget - 1)
        return {'add': [t1, t2]}
    numfields = [f for f in schema if f['type'] in NUM]
    f = rnd.choice(numfields)
    a = rnd.randrange(k)
    b = rnd.randrange(a, k)
    return {'aggregate': rnd.choice(['sum', 'mean', 'min', 'max']),
            'field': f['name'], 'from': a, 'to': b}


def gen_comparison(rnd, schema, k, dollar_ok):
    f = rnd.choice(schema)
    t = f['type']
    ops = ['eq', 'ne'] if t in ('ID', 'FLAG') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge']
    left = gen_term(rnd, [f], k, dollar_ok, 2)
    style = rnd.random()
    if style < 0.5:
        right = gen_term(rnd, [f], k, dollar_ok, 2)
    else:
        if t in NUM:
            right = {'const': rnd.randint(f['min'], f['max']), 'type': t}
        elif t == 'ID':
            right = {'const': rnd.choice(f['values']) if rnd.random() < 0.7
                     else rand_id_string(rnd), 'type': 'ID'}
        else:
            right = {'const': rnd.random() < 0.5, 'type': 'FLAG'}
    return {'cmp': rnd.choice(ops), 'left': left, 'right': right}


def gen_atom(rnd, schema, k):
    if rnd.random() < 0.35:
        a = rnd.randrange(k)
        z = rnd.randrange(a, k)
        return {'quantifier': rnd.choice(['any', 'all']), 'from': a, 'to': z,
                'predicate': gen_comparison(rnd, schema, k, True)}
    return gen_comparison(rnd, schema, k, False)


def gen_trace(rnd, schema, k, tid, prefix_len=None):
    n = rnd.randint(0, 12)
    times = rnd.sample(range(-100, 100), n)
    rows = []
    for t in times:
        vals = []
        for f in schema:
            if f['type'] in NUM:
                vals.append(rnd.randint(f['min'], f['max']))
            elif f['type'] == 'ID':
                vals.append(rnd.choice(f['values']))
            else:
                vals.append(rnd.random() < 0.5)
        rows.append({'t': t, 'values': vals})
    rnd.shuffle(rows)
    return {'id': tid, 'source': 'src%d' % rnd.randint(0, 3), 'rows': rows}


def gen_request(rnd, seed=None):
    rnd = rnd
    nf = rnd.randint(1, 4)
    schema = []
    used = set()
    for _ in range(nf):
        while True:
            name = rand_name(rnd)
            if name not in used:
                used.add(name)
                break
        t = rnd.choice(['TIME', 'SIZE', 'COUNT', 'ID', 'FLAG'])
        if t in NUM:
            lo = rnd.randint(-5, 5)
            hi = lo + rnd.randint(0, 8)
            schema.append({'name': name, 'type': t, 'min': lo, 'max': hi})
        elif t == 'ID':
            vals = []
            while len(vals) < rnd.randint(1, 4):
                v = rand_id_string(rnd)
                if v not in vals:
                    vals.append(v)
            schema.append({'name': name, 'type': 'ID', 'values': vals})
        else:
            schema.append({'name': name, 'type': 'FLAG'})
    k = rnd.randint(1, 4)
    natoms = rnd.randint(0, 4)
    atoms = []
    base = [gen_atom(rnd, schema, k) for _ in range(natoms)]
    for i in range(natoms):
        if base and rnd.random() < 0.25:
            atoms.append(json.loads(json.dumps(rnd.choice(base))))
        else:
            atoms.append(gen_atom(rnd, schema, k))
    req = {
        'version': 1,
        'schema': schema,
        'window': k,
        'atoms': atoms,
        'policy': {'max_width': rnd.randint(1, 3),
                   'min_support': rnd.randint(1, 3),
                   'min_witness': rnd.randint(1, 3)},
        'train': [],
        'probes': [],
        'queries': [],
    }
    tid = 0
    for part, count in (('train', rnd.randint(0, 4)), ('probes', rnd.randint(0, 3)),
                        ('queries', rnd.randint(0, 3))):
        arr = []
        for _ in range(count):
            arr.append(gen_trace(rnd, schema, k, 't%d' % tid))
            tid += 1
        req[part] = arr
    return req
