def validate_schema(arr):
    """Return (names, types, domains)."""
    if type(arr) is not list or not (1 <= len(arr) <= 32):
        schema_fail()
    names = []
    types = []
    domains = []
    seen = set()
    for field in arr:
        if type(field) is not dict:
            schema_fail()
        keys = set(field.keys())
        if 'name' not in keys or 'type' not in keys:
            schema_fail()
        name = field['name']
        if type(name) is not str or not NAME_RE.fullmatch(name):
            schema_fail()
        ftype = field['type']
        if name in seen:
            schema_fail()
        seen.add(name)
        if ftype == 'TIME' or ftype == 'SIZE' or ftype == 'COUNT':
            if keys != {'name', 'type', 'min', 'max'}:
                schema_fail()
            lo = field['min']
            hi = field['max']
            if type(lo) is not int or type(hi) is not int:
                schema_fail()
            if not (INT32_MIN <= lo <= INT32_MAX) or not (INT32_MIN <= hi <= INT32_MAX):
                schema_fail()
            if lo > hi:
                schema_fail()
            domains.append((lo, hi))
        elif ftype == 'ID':
            if keys != {'name', 'type', 'values'}:
                schema_fail()
            values = field['values']
            if type(values) is not list or not (1 <= len(values) <= 32):
                schema_fail()
            vset = set()
            for val in values:
                if type(val) is not str or not IDVAL_RE.fullmatch(val):
                    schema_fail()
                if val in vset:
                    schema_fail()
                vset.add(val)
            domains.append(frozenset(vset))
        elif ftype == 'FLAG':
            if keys != {'name', 'type'}:
                schema_fail()
            domains.append(None)
        else:
            schema_fail()
        names.append(name)
        types.append(ftype)
    return names, types, domains


