    'le': lambda a, b: a <= b,
    'gt': lambda a, b: a > b,
    'ge': lambda a, b: a >= b,
}


def compile_comparison(node, k, dollar_ok, ftypes, fidx):
    """Return (fn(ctx, dollar_row) -> bool, node_count)."""
    if type(node) is not dict or set(node.keys()) != {'cmp', 'left', 'right'}:
        schema_fail()
    op = node['cmp']
    if type(op) is not str or op not in CMP_OPS:
        schema_fail()
    t1, f1, n1, d1 = compile_term(node['left'], k, dollar_ok, ftypes, fidx)
    t2, f2, n2, d2 = compile_term(node['right'], k, dollar_ok, ftypes, fidx)
    if t1 != t2:
        schema_fail()
    if n1 + n2 > 64:
        schema_fail()
    if d1 > 4 or d2 > 4:
        schema_fail()
    if t1 not in NUMERIC_TYPES and op not in ('eq', 'ne'):
        schema_fail()
    cmp_fn = _CMP_FNS[op]
    fn = lambda ctx, dr, _a=f1, _b=f2, _c=cmp_fn: _c(_a(ctx, dr), _b(ctx, dr))
    return fn, n1 + n2


def compile_atom(node, k, ftypes, fidx):
    """Return fn(ctx) -> bool."""
    if type(node) is not dict:
        schema_fail()
    keys = set(node.keys())
    if keys == {'quantifier', 'from', 'to', 'predicate'}:
        quant = node['quantifier']
        if type(quant) is not str or quant not in ('any', 'all'):
            schema_fail()
        lo = node['from']
        hi = node['to']
        if type(lo) is not int or type(hi) is not int:
            schema_fail()
        if not (0 <= lo <= hi < k):
            schema_fail()
        pred, _ = compile_comparison(node['predicate'], k, True, ftypes, fidx)
        if lo == hi:
            return lambda ctx, _p=pred, _o=lo: _p(ctx, ctx[_o])
        if quant == 'any':
            return (lambda ctx, _p=pred, _a=lo, _z=hi:
                    any(_p(ctx, ctx[o]) for o in range(_a, _z + 1)))
        return (lambda ctx, _p=pred, _a=lo, _z=hi:
                all(_p(ctx, ctx[o]) for o in range(_a, _z + 1)))
    fn, _ = compile_comparison(node, k, False, ftypes, fidx)
    return lambda ctx, _p=fn: _p(ctx, None)


