def iter_clauses(natoms, max_width):
    top = max_width if max_width < natoms else natoms
    for width in range(1, top + 1):
        for combo in combinations(range(natoms), width):
            if width == 1:
                yield (combo[0] * 2,)
                yield (combo[0] * 2 + 1,)
            else:
                for signs in product((0, 1), repeat=width):
                    yield tuple(combo[j] * 2 + signs[j] for j in range(width))


def train_source_masks(source_names, ctx_sources, n_train):
    masks = []
    for name in source_names:
        mask = 0
        bit = 1
        for src in ctx_sources:
            if src == name:
                mask |= bit
            bit <<= 1
        masks.append(mask)
    return masks


